import React, { useState } from "react";
import api from "../api";

export default function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    message: "",
  });
  const [status, setStatus] = useState("");

  const change = (e) => setForm((f) => ({ ...f, [e.target.name]: e.target.value }));

  const submit = async (e) => {
    e.preventDefault();
    setStatus("Sending...");
    try {
      await api.post("/contact", form);
      setStatus("Message sent. Thank you!");
      setForm({ name: "", email: "", phone: "", message: "" });
    } catch (err) {
      setStatus("Send failed. Please try again.");
    }
  };

  return (
    <div className="container card">
      <h2>Contact Us</h2>
      <div className="two-col">
        {/* ---- Left side box (menu-like section) ---- */}
        <div className="left">
          <div className="box">
            <h3>Quick Links</h3>
            <div className="rect-list">
              <div>School Location</div>
              <div>Contact Form</div>
              <div>Feedback</div>
            </div>
          </div>
        </div>

        {/* ---- Right side form and info ---- */}
        <div className="right">
          <h3>Get in Touch</h3>
          <p>We’d love to hear from you! Please fill out the form below.</p>

          <form onSubmit={submit}>
            <input
              name="name"
              placeholder="Your Name"
              value={form.name}
              onChange={change}
              required
            />
            <input
              name="email"
              placeholder="Your Email"
              value={form.email}
              onChange={change}
              required
            />
            <input
              name="phone"
              placeholder="Phone"
              value={form.phone}
              onChange={change}
            />
            <textarea
              name="message"
              placeholder="Message"
              value={form.message}
              onChange={change}
              required
            />
            <button type="submit">Send Message</button>
            <div className="status">{status}</div>
          </form>

          <div className="contact-info">
            <h4>Contact Info</h4>
            <p>📍 Near Gandhi Institute, Meerut, Uttar Pradesh</p>
            <p>📞 +91 9045032868</p>
            <p>
              📧 <a href="mailto:gipsmrt.in@gmail.com">gipsmrt.in@gmail.com</a>
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
